\resultentry{050}{A counterexample to Griffiths' positivity conjecture}{Constructs ample rank-two bundles on $\mathbb P^1\times\mathbb P^1$ with no smooth Hermitian metric of strictly Griffiths-positive curvature, disproving Griffiths' positivity conjecture already on the quadric surface.}{\href{https://github.com/openai/math/blob/main/preprints/ample-rank-two-bundles-on-the-quadric-surface-without-griffiths-positive-metrics-September-24-2026/paper.pdf}{Ample rank-two bundles on the quadric surface without Griffiths-positive metrics}}
